# port scan plugin
yakit.AutoInitYakit()

CVEs = []
addCVE = func(cve, rules, score, severity, titleZh, titleEn) {
    if (str.Contains(rules, ",")) {
        rules = str.Join(x.Map(str.Split(rules, ","), func(i) {
            return sprintf(`(%v)`, str.ReplaceAll(str.TrimSpace(i), ".", `\.`))
        }), "|")
    }
    CVEs = append(CVEs, {
        "cve": cve,
        "rule": rules,
        "score": score,
        "severity": severity,
        "titleZh": titleZh,
        "titleEn": titleEn, 
    })
}

addCVE("CVE-2021-28149", "3.0.5","6.5", "MEDIUM", "hongdian h8922_firmware 路径遍历漏洞", "Hongdian h8922_firmware path traversal vulnerability")
addCVE("CVE-2021-28150", "3.0.5","5.5", "MEDIUM", "hongdian h8922_firmware 输入验证不恰当漏洞", "Hongdian h8922_firmware Incorrect Input Validation Vulnerability")
addCVE("CVE-2021-28151", "3.0.5","8.8", "HIGH", "hongdian h8922_firmware os 命令注入漏洞", "Hongdian h8922_firmware OS command injection vulnerability")
addCVE("CVE-2021-28152", "3.0.5","9.8", "CRITICAL", "hongdian h8922_firmware 使用硬编码的凭证漏洞", "Hongdian h8922_firmware uses a hard-coded voucher vulnerability.")



handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen() {
        return
    }

    if result.Fingerprint == nil {
        return
    }
    if str.MatchAllOfRegexp(result.GetServiceName(),"(?i)hongdian|H8922") {
    yakit.Info("cves: %d", len(CVEs))

        x.Foreach(CVEs, func(i) {
            defer func{
                err = recover()
                if err != nil {
                    yakit.Error("Hongdian CVE 合规检查失败：%v", err)
                }
            }
            if !str.MatchAllOfRegexp(result.Fingerprint.Version, i.rule) {
                return
            }

            target := str.HostPort(result.Target, result.Port)
            targetOutput := sprintf("(%v)", target)
            risk.NewRisk(
                target, 
                risk.title(sprintf(`%v:%v%v`, i.cve, i["titleEn"], targetOutput)),
                risk.titleVerbose(sprintf(`%v:%v%v`, i.cve, i["titleZh"], targetOutput)),
                risk.type("cve-baseline"),
                risk.typeVerbose("CVE基线检查"),
                risk.parameter(result.Fingerprint.Banner),
                risk.potential(true),
                risk.level("low"),
                risk.details(i),
                risk.cve(i.cve),
            )
            println(i.cve)
        })
    }
}
